/// <summary>
/// Extension class for PriceDiscAdmCheckPost
/// </summary>
[ExtensionOf(classStr(PriceDiscAdmCheckPost))]
final class AVARUMPriceDiscAdmCheckPostCls_Extension
{
}

Method.Source:
/// <summary>
/// Extends the post of the journal process
/// </summary>
void postJournal()
{
    PriceDiscAdmTrans priceDiscAdmTrans;
    UnitOfMeasure priceDiscAdmTransUnit;
    AVARUMPriceDiscAutoGeneratedTmp priceDiscAutoGeneratedTmp;
    InventDim inventDim;
    InventDistinctProductExpanded inventDistinctProductExpanded;
    UnitOfMeasureConversion startPriceUOMConvBase;
    UnitOfMeasureConversion uomConv;
    UnitOfMeasure fromUnit;
    UnitOfMeasure toUnit;

    // Collections for batch operations
    Map productConversionMap = new Map(Types::Int64, Types::Container);
    Set processedRecIds = new Set(Types::Int64);

    next postJournal();

    if (!isPosted)
    {
        return;
    }

    delete_from priceDiscAutoGeneratedTmp
        where priceDiscAutoGeneratedTmp.JournalNum;

    // Step 1: Load all relevant data in a single query
    while select priceDiscAdmTrans
        order by
            priceDiscAdmTrans.ItemRelation asc,
            inventDim.configId asc,
            priceDiscAdmTrans.LineNum asc
        where priceDiscAdmTrans.JournalNum == journalNum &&
            priceDiscAdmTrans.ItemCode == PriceDiscProductCodeType::Table &&
            priceDiscAdmTrans.Module == ModuleInventCustVend::Cust &&
            priceDiscAdmTrans.MustBeDeleted == NoYes::No &&
            priceDiscAdmTrans.PriceDiscTableRef == 0
        join priceDiscAdmTransUnit
            where priceDiscAdmTransUnit.Symbol == priceDiscAdmTrans.UnitId
        join configId from inventDim
            where inventDim.InventDimId == priceDiscAdmTrans.InventDimId
        join Product from inventDistinctProductExpanded
            where inventDistinctProductExpanded.ItemId == priceDiscAdmTrans.ItemRelation &&
                    inventDistinctProductExpanded.configId == inventDim.configId
    {
        // Find base band conversion
        select firstonly startPriceUOMConvBase
        where startPriceUOMConvBase.Product == inventDistinctProductExpanded.Product &&
                startPriceUOMConvBase.AVARUMUnitOrder > 0 &&
                (startPriceUOMConvBase.FromUnitOfMeasure == priceDiscAdmTransUnit.RecId ||
                startPriceUOMConvBase.ToUnitOfMeasure == priceDiscAdmTransUnit.RecId);

        /// If no conversion is found to the base band, we cannot determine the position of the unit and therefore cannot process the record, so we skip it.
        if (!startPriceUOMConvBase)
        {
            continue;
        }

        // Generate auto-generated tmp records
        this.generateAutoGeneratedTmpRecords
        (
            priceDiscAutoGeneratedTmp,
            priceDiscAdmTrans,
            inventDistinctProductExpanded.Product,
            startPriceUOMConvBase,
            priceDiscAdmTransUnit.RecId
        );

        /// Add to set to process in batch later
        processedRecIds.add(priceDiscAdmTrans.RecId);
    }

    // Step 2: Batch processing for Below records
    this.processPriceDiscRecordsBelow(priceDiscAutoGeneratedTmp, processedRecIds);

    // Step 3: Batch processing for Above records
    this.processPriceDiscRecordsAbove(priceDiscAutoGeneratedTmp, processedRecIds);

    // Step 4: Cleanup
    delete_from priceDiscAutoGeneratedTmp
        where priceDiscAutoGeneratedTmp.JournalNum;
}

/// <summary>
/// Generates temporary records for price discount adjustments.
/// </summary>
/// <param name = "_tmp">The temporary table buffer.</param>
/// <param name = "_priceDiscAdmTrans">The price discount administration transaction record.</param>
/// <param name = "_product">The product for which the price discount is being processed.</param>
/// <param name = "_startPriceUOMConvBase">The unit of measure conversion record for the starting price band.</param>
/// <param name = "_priceDiscAdmTransUnitRecId">The record ID of the unit of measure used in the price discount administration transaction.</param>
private void generateAutoGeneratedTmpRecords
(
    AVARUMPriceDiscAutoGeneratedTmp _tmp,
    PriceDiscAdmTrans _priceDiscAdmTrans,
    RefRecId _product,
    UnitOfMeasureConversion _startPriceUOMConvBase,
    RefRecId _priceDiscAdmTransUnitRecId
)
{
    UnitOfMeasureConversion uomConv;
    UnitOfMeasure fromUnit, toUnit;
    RecordInsertList insertList = new RecordInsertList(tableNum(AVARUMPriceDiscAutoGeneratedTmp), false, false, false, false, true, _tmp);

    while select uomConv
        order by uomConv.AVARUMUnitOrder asc
        where uomConv.Product == _product &&
                uomConv.AVARUMUnitOrder > 0
        join Symbol from fromUnit
            where fromUnit.RecId == uomConv.FromUnitOfMeasure
        join Symbol from toUnit
            where toUnit.RecId == uomConv.ToUnitOfMeasure
    {
        _tmp.clear();
        _tmp.initValue();
        _tmp.JournalNum = _priceDiscAdmTrans.JournalNum;
        _tmp.LineNum = _priceDiscAdmTrans.LineNum;
        _tmp.PriceDiscAdmTransRefRecId = _priceDiscAdmTrans.RecId;
        _tmp.UnitOrder = uomConv.AVARUMUnitOrder;
        _tmp.UnitFactor = uomConv.Factor;

        // Determine position (simplified logic)
        this.determineUnitPosition
        (
            _tmp,
            uomConv,
            _startPriceUOMConvBase,
            _priceDiscAdmTransUnitRecId,
            fromUnit,
            toUnit
        );

        if (_tmp.UnitSymbol)
        {
            insertList.add(_tmp);
        }
    }

    insertList.insertDatabase();

    var tmpTableName = _tmp.getPhysicalTableName();
}

/// <summary>
/// Determines the position of the unit of measure in relation to the starting price band.
/// </summary>
/// <param name = "_tmp">The temporary table buffer.</param>
/// <param name = "_uomConv">The unit of measure conversion record.</param>
/// <param name = "_startPriceUOMConvBase">The unit of measure conversion record for the starting price band.</param>
/// <param name = "_priceDiscAdmTransUnitRecId">The record ID of the unit of measure used in the price discount administration transaction.</param>
/// <param name = "_fromUnit">The unit of measure being converted from.</param>
/// <param name = "_toUnit">The unit of measure being converted to.</param>
private void determineUnitPosition
(
    AVARUMPriceDiscAutoGeneratedTmp _tmp,
    UnitOfMeasureConversion _uomConv,
    UnitOfMeasureConversion _startPriceUOMConvBase,
    RefRecId _priceDiscAdmTransUnitRecId,
    UnitOfMeasure _fromUnit,
    UnitOfMeasure _toUnit)
{
    int orderPosCurrent = _uomConv.AVARUMUnitOrder;
    int orderPosPrice = _startPriceUOMConvBase.AVARUMUnitOrder;

    if (orderPosCurrent < orderPosPrice)
    {
        _tmp.UnitOrderPosition = AVARUMPriceDiscUnitOrderPosition::Below;
        _tmp.UnitSymbol = _toUnit.Symbol;
        _tmp.UnitRefRecId = _toUnit.RecId;
    }
    else if (orderPosCurrent > orderPosPrice)
    {
        _tmp.UnitOrderPosition = AVARUMPriceDiscUnitOrderPosition::Above;
        _tmp.UnitSymbol = _fromUnit.Symbol;
        _tmp.UnitRefRecId = _fromUnit.RecId;
    }
    else
    {
        if (_uomConv.RecId == _startPriceUOMConvBase.RecId)
        {
            if (_priceDiscAdmTransUnitRecId == _startPriceUOMConvBase.FromUnitOfMeasure)
            {
                _tmp.UnitOrderPosition = AVARUMPriceDiscUnitOrderPosition::Below;
                _tmp.UnitSymbol = _toUnit.Symbol;
                _tmp.UnitRefRecId = _toUnit.RecId;
            }
            else
            {
                _tmp.UnitOrderPosition = AVARUMPriceDiscUnitOrderPosition::Above;
                _tmp.UnitSymbol = _fromUnit.Symbol;
                _tmp.UnitRefRecId = _fromUnit.RecId;
            }
        }
        else
        {
            if (_fromUnit.RecId == _priceDiscAdmTransUnitRecId)
            {
                _tmp.UnitOrderPosition = AVARUMPriceDiscUnitOrderPosition::Above;
                _tmp.UnitSymbol = _toUnit.Symbol;
                _tmp.UnitRefRecId = _toUnit.RecId;
            }
            else if (_toUnit.RecId == _priceDiscAdmTransUnitRecId)
            {
                _tmp.UnitOrderPosition = AVARUMPriceDiscUnitOrderPosition::Below;
                _tmp.UnitSymbol = _fromUnit.Symbol;
                _tmp.UnitRefRecId = _fromUnit.RecId;
            }
        }
    }
}

/// <summary>
/// Processes price discount records that are below the starting price band.
/// </summary>
/// <param name = "_tmp">The temporary table buffer.</param>
/// <param name = "_processedRecIds">The set of processed record IDs.</param>
private void processPriceDiscRecordsBelow(AVARUMPriceDiscAutoGeneratedTmp _tmp, Set _processedRecIds)
{
    PriceDiscAdmTrans priceDiscAdmTransBelow;
    InventDim inventDimBelow;
    InventDistinctProductExpanded inventDistinctProductExpandedBelow;
    UnitOfMeasureConversion startPriceUOMConvBase;
    RecordInsertList insertList = new RecordInsertList(tableNum(PriceDiscTable));
    Map factorCache = new Map(Types::Int64, Types::Container); 

    while select priceDiscAdmTransBelow
        order by
            priceDiscAdmTransBelow.ItemRelation asc,
            inventDimBelow.configId asc,
            priceDiscAdmTransBelow.LineNum asc,
            _tmp.UnitOrder desc
        where priceDiscAdmTransBelow.JournalNum == journalNum &&
            priceDiscAdmTransBelow.ItemCode == PriceDiscProductCodeType::Table &&
            priceDiscAdmTransBelow.Module == ModuleInventCustVend::Cust &&
            priceDiscAdmTransBelow.MustBeDeleted == NoYes::No &&
            priceDiscAdmTransBelow.PriceDiscTableRef == 0
        join _tmp
            where _tmp.PriceDiscAdmTransRefRecId == priceDiscAdmTransBelow.RecId &&
            _tmp.UnitOrderPosition == AVARUMPriceDiscUnitOrderPosition::Below
        join configId from inventDimBelow
            where inventDimBelow.InventDimId == priceDiscAdmTransBelow.InventDimId
        join Product from inventDistinctProductExpandedBelow
            where inventDistinctProductExpandedBelow.ItemId == priceDiscAdmTransBelow.ItemRelation &&
                inventDistinctProductExpandedBelow.configId == inventDimBelow.configId
    {
        UnitOfMeasureConversionFactor baseFactor = 1;
        UnitOfMeasureConversionFactor prevFactor = 1;

        // Use factor cache
        if (factorCache.exists(priceDiscAdmTransBelow.RecId))
        {
            container factorCont = factorCache.lookup(priceDiscAdmTransBelow.RecId);
            baseFactor = conPeek(factorCont, 1);
            prevFactor = conPeek(factorCont, 2);
        }
        else
        {
            select firstonly startPriceUOMConvBase
            where startPriceUOMConvBase.Product == inventDistinctProductExpandedBelow.Product &&
                    startPriceUOMConvBase.AVARUMUnitOrder > 0;

            if (_tmp.UnitOrder == startPriceUOMConvBase.AVARUMUnitOrder)
            {
                baseFactor = startPriceUOMConvBase.Factor;
                prevFactor = 1;
            }
            else
            {
                prevFactor = prevFactor * _tmp.UnitFactor;
            }

            factorCache.insert(priceDiscAdmTransBelow.RecId, [baseFactor, prevFactor]);
        }

        PriceDiscTable priceDiscTable;

        /// Price unit should be the same and taken from the original record, 
        /// so we can use the same factor to convert the amount.
        priceDiscTable.initFromPriceDiscAdm_AVA(priceDiscAdmTransBelow);
        priceDiscTable.AVARUMIsPriceAutoGenerated = NoYes::Yes;
        priceDiscTable.UnitId = _tmp.UnitSymbol;
        priceDiscTable.Amount = (priceDiscTable.Amount / priceDiscTable.PriceUnit / baseFactor) / prevFactor;
        priceDiscTable.PriceUnit = 1;

        insertList.add(priceDiscTable);
    }

    insertList.insertDatabase();
}

/// <summary>
/// Processes price discount records that are above the starting price band.
/// </summary>
/// <param name = "_tmp">The temporary table buffer.</param>
/// <param name = "_processedRecIds">The set of processed record IDs.</param>
private void processPriceDiscRecordsAbove(AVARUMPriceDiscAutoGeneratedTmp _tmp, Set _processedRecIds)
{
    PriceDiscAdmTrans priceDiscAdmTransAbove;
    InventDim inventDimAbove;
    InventDistinctProductExpanded inventDistinctProductExpandedAbove;
    RecordInsertList insertList = new RecordInsertList(tableNum(PriceDiscTable));
    Map factorCache = new Map(Types::Int64, Types::Real);

    while select priceDiscAdmTransAbove
        order by
            priceDiscAdmTransAbove.ItemRelation asc,
            inventDimAbove.configId asc,
            priceDiscAdmTransAbove.LineNum asc,
            _tmp.UnitOrder asc
        where priceDiscAdmTransAbove.JournalNum == journalNum &&
            priceDiscAdmTransAbove.ItemCode == PriceDiscProductCodeType::Table &&
            priceDiscAdmTransAbove.Module == ModuleInventCustVend::Cust &&
            priceDiscAdmTransAbove.MustBeDeleted == NoYes::No &&
            priceDiscAdmTransAbove.PriceDiscTableRef == 0
        join _tmp
            where _tmp.PriceDiscAdmTransRefRecId == priceDiscAdmTransAbove.RecId &&
            _tmp.UnitOrderPosition == AVARUMPriceDiscUnitOrderPosition::Above
        join configId from inventDimAbove
            where inventDimAbove.InventDimId == priceDiscAdmTransAbove.InventDimId
        join Product from inventDistinctProductExpandedAbove
            where inventDistinctProductExpandedAbove.ItemId == priceDiscAdmTransAbove.ItemRelation &&
                inventDistinctProductExpandedAbove.configId == inventDimAbove.configId
    {
        UnitOfMeasureConversionFactor baseFactor = 1;

        if (factorCache.exists(priceDiscAdmTransAbove.RecId))
        {
            baseFactor = factorCache.lookup(priceDiscAdmTransAbove.RecId);
        }

        baseFactor = baseFactor * _tmp.UnitFactor;
        factorCache.insert(priceDiscAdmTransAbove.RecId, baseFactor);

        PriceDiscTable priceDiscTable;
        priceDiscTable.initFromPriceDiscAdm_AVA(priceDiscAdmTransAbove);
        priceDiscTable.AVARUMIsPriceAutoGenerated = NoYes::Yes;
        priceDiscTable.UnitId = _tmp.UnitSymbol;
        priceDiscTable.Amount = (priceDiscTable.Amount * baseFactor) / priceDiscTable.PriceUnit;
        priceDiscTable.PriceUnit = 1;

        insertList.add(priceDiscTable);
    }

    insertList.insertDatabase();
}
